7]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4DiagKit; @DK; @u8_ext]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4DiagGlue; @DG; @PRE7_eq]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4DiagStrnlen; @DSN; @cstr_ext]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4DiagStrnlen; @DSN; @cstr]; [@Corelib; @Init; @Nat; @add]; [@Corelib; @Init; @Datatypes; @app]; [@Corelib; @Init; @Peano; @lt]; [@Corelib; @Lists; @ListDef; @nth]; [@Corelib; @Lists; @ListDef; @firstn]; [@stdpp; @tactics; @f_equal_help]; [@Corelib; @Init; @Nat; @sub]; [@Stdlib; @Lists; @List; @app_nil_r]; [@Stdlib; @Arith; @PeanoNat; @Nat; @sub]; [@Stdlib; @Arith; @PeanoNat; @Nat; @sub_diag]; [@Stdlib; @Lists; @List; @firstn_all2]; [@Stdlib; @micromega; @ZifyClasses; @rew_iff_rev]; [@Corelib; @Init; @Peano; @le]; [@Stdlib; @micromega; @ZifyClasses; @mkrel]; [@Stdlib; @ZArith; @Znat; @Nat2Z; @inj_le]; [@Stdlib; @Lists; @List; @firstn_app]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @SeqExec; @rdn_firstn]; [@Stdlib; @micromega; @ZifyClasses; @mkapp2]; [@Stdlib; @Arith; @PeanoNat; @Nat; @add]; [@Stdlib; @ZArith; @Znat; @Nat2Z; @inj_add]; [@Corelib; @Init; @Logic; @ex_intro]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @CatSim; @msteps_trans]; [@Corelib; @Init; @Logic; @or_intror]; [@Corelib; @Init; @Logic; @or_introl]; [@Corelib; @Init; @Logic; @or_ind]; [@Corelib; @Init; @Logic; @False_ind]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4DiagKit; @DK; @zeros_ext]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4RegionPoisoned; @SB]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @L5KnA; @L5KA; @zeros_at]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4DiagGlue; @DG; @u8_of_u32_5]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @asan; @Pm4DiagUP; @AS0DIAGUP; @duEc_conc]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @asan; @Pm4DiagUP; @AS0DIAGUP; @KS_duEc]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4DiagKit; @DK; @UR]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @L5Kn; @L5K; @in_b]; [@Stdlib; @Lists; @List; @existsb]; [@Stdlib; @Arith; @PeanoNat; @Nat; @eqb]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4DiagKit; @DK; @U_to]; [@Stdlib; @micromega; @EnvRing; @PEopp]; [@Stdlib; @ZArith; @Zdiv; @Z_div_plus_full]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @L5KnA; @L5KA; @zeros_at_sub]; [@LinuxProcessSemantics; @LinuxProcessSem; @RiscvSemantics; @word_to_le_bytes]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4DiagGlue; @DG; @rdn_43]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4DiagGlue; @DG; @SUF7_eq]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @asan; @Pm4DiagUP; @AS0DIAGUP; @duGc_conc]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @asan; @Pm4DiagUP; @AS0DIAGUP; @KS_duGc]; [@Corelib; @Init; @Logic; @eq_sym]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4DiagUsagePre; @DUP; @usage_pre]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4DiagUsageC; @DUC; @UA; @usage_C_tail]].
 Local Ltac lia := L5FastLia.plia.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Module DUC.
Import DK. Import DSN. Import DG. Import AS0DIAGUP.

Section UA.
  Context (fx : FPState).
  Variables (R : bvmap 5 word) (M : word -> option byte) (S p can : Z) (bs t8 : list byte).
  #[local] Notation n := (Z.of_nat (length bs)).
  Hypothesis G1 : getr R (reg 1) = Z_to_bv 64 721508.        (* [comment removed for export] *)
  Hypothesis G2 : getr R (reg 2) = Z_to_bv 64 S.
  Hypothesis G10 : getr R (reg 10) = Z_to_bv 64 1463368.      (* [comment removed for export] *)
  Hypothesis G11 : getr R (reg 11) = Z_to_bv 64 91831.       (* [comment removed for export] *)
  Hypothesis G12 : getr R (reg 12) = Z_to_bv 64 p.           (* [comment removed for export] *)
  Hypothesis HS : 140735332552704 + 5440 <= S <= 140737488355328.
  Hypothesis Hal : S mod 16 = 0.
  Hypothesis HW : L5.writable RSEGS M (S - 5440) 5440.
  Hypothesis HD : L5.defined M (S - 5440) 5440.
  Hypothesis HIMG : L5.img_clear M 65536 1449984.
  Hypothesis Hp : S <= p /\ p + n + 1 + 16 <= 2 ^ 47.
  Hypothesis Hn : 74 <= n <= 131071.
  Hypothesis HSTR : cstr M p bs t8.
  Hypothesis HSH : forall x : word, SB + p / 8 - 7 <= bv_unsigned x < Z.min (SB + (p + n) / 8 + 8) (SB + 2 ^ 44) -> M x = Some (Z_to_bv 8 0).
  Hypothesis HSTK : L5KA.zeros_at M (SB + S / 8 - 680) 688.     (* [comment removed for export] *)
  Hypothesis HFMT : L5KA.zeros_at M 2147462352 16.               (* [comment removed for export] *)
  Hypothesis Hcan : 0 <= can < 2 ^ 64.
  Hypothesis HC : diag_cells M can.
  Hypothesis HSN : sn_cells M.
  Hypothesis HMC : mc_icpt_globs M.
  (* [comment removed for export] *)
  Variables m1 m2 m3 m4 m5 m6 m7 m8 : Z.
  Hypothesis Hm : (0 <= m1 < 2 ^ 64 /\ 0 <= m2 < 2 ^ 64 /\ 0 <= m3 < 2 ^ 64 /\ 0 <= m4 < 2 ^ 64) /\ (0 <= m5 < 2 ^ 64 /\ 0 <= m6 < 2 ^ 64 /\ 0 <= m7 < 2 ^ 64 /\ 0 <= m8 < 2 ^ 64).
  Hypothesis HMF : L5.u64_at RSEGS M (S + 72) 1315404 /\ L5.u64_at RSEGS M (S + 64) m1 /\ L5.u64_at RSEGS M (S + 56) m2 /\ L5.u64_at RSEGS M (S + 48) m3 /\ L5.u64_at RSEGS M (S + 40) m4
                   /\ L5.u64_at RSEGS M (S + 32) m5 /\ L5.u64_at RSEGS M (S + 24) m6 /\ L5.u64_at RSEGS M (S + 16) m7 /\ L5.u64_at RSEGS M (S + 8) m8.

  Theorem usage_C_tail : forall fx5 R5 M5, DUP.usage_mid R M S p can bs m1 m2 m3 m4 m5 m6 m7 m8 R5 M5 ->
    exists fxE RE ME,
      msteps RSEGS (st fx5 R5 0x14afcc M5) (st fxE RE 0x1493f8 ME)
      (* [comment removed for export] *)
      /\ getr RE (reg 17) = Z_to_bv 64 66 /\ getr RE (reg 10) = Z_to_bv 64 2 /\ getr RE (reg 11) = Z_to_bv 64 (S - 1128) /\ getr RE (reg 12) = Z_to_bv 64 2
      /\ getr RE (reg 9) = Z_to_bv 64 1463368 /\ getr RE (reg 18) = Z_to_bv 64 2 /\ getr RE (reg 19) = Z_to_bv 64 (S - 1128) /\ getr RE (reg 22) = Z_to_bv 64 (n + 7)
      /\ L5.u64_at RSEGS ME (S - 1128) (S - 464) /\ L5.u64_at RSEGS ME (S - 1120) 7 /\ L5.u64_at RSEGS ME (S - 1112) p /\ L5.u64_at RSEGS ME (S - 1104) n
      /\ rdn RSEGS ME (Z_to_bv 64 (S - 464)) 7 = Some PRE7 /\ rdn RSEGS ME (Z_to_bv 64 p) (length bs) = Some bs
      /\ L5.u32_at RSEGS ME 1463488 2
      /\ agree0 M ME S /\ mem_grows M ME
      /\ (forall fx' RX MX,
            (forall x : word, ~ (S - 1128 <= bv_unsigned x < S - 1096) -> MX x = ME x) -> mem_grows ME MX ->
            (forall k, In k [2; 3; 4; 8; 9; 21; 23; 24; 25; 26; 27]%nat -> getr RX (reg k) = getr RE (reg k)) ->
            exists fxE2 RE2 ME2,
              msteps RSEGS (st fx' RX 0x149404 MX) (st fxE2 RE2 0x1493f8 ME2)
              (* [comment removed for export] *)
              /\ getr RE2 (reg 17) = Z_to_bv 64 66 /\ getr RE2 (reg 10) = Z_to_bv 64 2 /\ getr RE2 (reg 11) = Z_to_bv 64 (S - 584) /\ getr RE2 (reg 12) = Z_to_bv 64 2
              /\ getr RE2 (reg 9) = Z_to_bv 64 1463368 /\ getr RE2 (reg 18) = Z_to_bv 64 2 /\ getr RE2 (reg 19) = Z_to_bv 64 (S - 584) /\ getr RE2 (reg 22) = Z_to_bv 64 7
              /\ L5.u64_at RSEGS ME2 (S - 584) (S - 464) /\ L5.u64_at RSEGS ME2 (S - 576) 7 /\ L5.u64_at RSEGS ME2 (S - 568) 0 /\ L5.u64_at RSEGS ME2 (S - 560) 0
              /\ rdn RSEGS ME2 (Z_to_bv 64 (S - 464)) 7 = Some SUF7
              /\ L5.u32_at RSEGS ME2 1463488 2
              /\ agree0 M ME2 S /\ mem_grows M ME2
              /\ (forall fx'' RY MY,
                    (forall x : word, ~ (S - 584 <= bv_unsigned x < S - 552) -> MY x = ME2 x) -> mem_grows ME2 MY ->
                    (forall k, In k [2; 3; 4; 8; 9; 21; 23; 24; 25; 26; 27]%nat -> getr RY (reg k) = getr RE2 (reg k)) ->
                    exists fxF RF MF,
                      msteps RSEGS (st fx'' RY 0x149404 MY) (st fxF RF 0x141a14 MF)
                      /\ getr RF (reg 10) = getr R (reg 8) /\ getr RF (reg 2) = Z_to_bv 64 (S + 80)
                      /\ agree0 M MF S /\ mem_grows M MF
